-- UniAttend 0009 — institution-neutral setup: campus maps and timetable sources
-- per institution, and a platform directory of known institutions.
--
-- * campuses: an outline and zoom so each institution's map opens on its own
--   campuses (nothing about any institution is hard-coded in the app).
-- * institution_settings: where the institution's timetable is collected from.
-- * institution_directory: the super admin's catalogue of known institutions,
--   their campus locations and timetable links, applied to an institution in
--   one step when it registers. Only the super admin can see or change it.

alter table uniattend.campuses
  add column if not exists town text check (town is null or length(town) <= 120),
  add column if not exists zoom int not null default 16 check (zoom between 3 and 20),
  add column if not exists outline jsonb check (outline is null or (jsonb_typeof(outline) = 'array' and jsonb_array_length(outline) between 3 and 500)),
  add column if not exists osm_ref text check (osm_ref is null or osm_ref ~ '^(node|way|relation)/[0-9]+$');

alter table uniattend.institution_settings
  add column if not exists timetable_source_type text not null default 'none'
    check (timetable_source_type in ('none','viewer_json','pdf_links','pdf_url')),
  add column if not exists timetable_source_url text
    check (timetable_source_url is null or timetable_source_url ~ '^https://[^\s"''<>]+$');

-- Institution admins may not point the server at arbitrary URLs: only the
-- super admin sets the timetable source.
create or replace function uniattend.guard_timetable_source()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if (new.timetable_source_type is distinct from old.timetable_source_type
      or new.timetable_source_url is distinct from old.timetable_source_url)
     and auth.uid() is not null and not uniattend.is_super_admin() then
    raise exception 'Only the platform administrator can change where timetables are collected from.' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists institution_settings_timetable_guard on uniattend.institution_settings;
create trigger institution_settings_timetable_guard before update on uniattend.institution_settings
  for each row execute function uniattend.guard_timetable_source();

create table if not exists uniattend.institution_directory (
  id                    uuid primary key default gen_random_uuid(),
  name                  text not null unique check (length(trim(name)) between 2 and 200),
  short_name            text,
  kind                  text not null default 'university' check (kind in ('university','university_of_technology','tvet_college','college')),
  province              text,
  website               text check (website is null or website ~ '^https://'),
  timetable_source_type text not null default 'none' check (timetable_source_type in ('none','viewer_json','pdf_links','pdf_url')),
  timetable_source_url  text check (timetable_source_url is null or timetable_source_url ~ '^https://[^\s"''<>]+$'),
  timetable_note        text,
  campuses              jsonb not null default '[]'::jsonb check (jsonb_typeof(campuses) = 'array'),
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);
drop trigger if exists institution_directory_touch on uniattend.institution_directory;
create trigger institution_directory_touch before update on uniattend.institution_directory
  for each row execute function uniattend.touch_updated_at();

alter table uniattend.institution_directory enable row level security;
drop policy if exists institution_directory_super on uniattend.institution_directory;
create policy institution_directory_super on uniattend.institution_directory for all to authenticated
  using (uniattend.is_super_admin()) with check (uniattend.is_super_admin());

alter table uniattend.institutions add column if not exists directory_id uuid references uniattend.institution_directory(id) on delete set null;

revoke all on function uniattend.guard_timetable_source() from public, anon;

